import {mountSceneReferences} from './scene-references.js';
import {mountConnections} from './connections.js';
import {uid,escapeHTML as e,plain} from './store.js';
import {editorMarkup,mountEditor} from './editor.js';
import {documentTargets} from './document-links.js';
export const defaultMonths=()=>['Aurora','Bruma','Florália','Solalto','Âmbar','Geada'].map(name=>({name,days:30}));
export function initNarrative(w){if(!w.narrative){w.narrative={relations:[],events:[],scenes:[],calendar:{months:defaultMonths(),weekdays:['Sol','Lua','Estrela','Terra','Vento'],era:'Era atual'}};for(const t of ['connections','timeline','scenes'])if(!w.enabled.includes(t))w.enabled.push(t);}const n=w.narrative;if(!Array.isArray(n.relations)||!Array.isArray(n.events)||!Array.isArray(n.scenes)||!Array.isArray(n.calendar?.months)||!n.calendar.months.length||n.calendar.months.some(m=>!Number.isInteger(m.days)||m.days<1||m.days>365)||!Array.isArray(n.calendar.weekdays)||!n.calendar.weekdays.length)throw Error('Dados narrativos inválidos.');return n;}
export function loreTargets(w){return [...documentTargets(w).map(d=>({...d,name:d.title,kind:'Documento',description:plain([...w.notes,...w.folderNotes].find(n=>n.id===d.id)?.body||'')})),...['characters','bestiary','plot'].flatMap(k=>w[k].map(x=>({id:x.id,name:x.name||x.title,kind:k==='characters'?'Personagem':k==='bestiary'?'Criatura':'Trama',description:x.description||''}))),...w.maps.flatMap(m=>m.pins.map(p=>({id:p.id,name:p.name,kind:'Lugar',description:p.description||''})))];}
export function fictionalOrdinal(ev,calendar){return Number(ev.year)*calendar.months.reduce((s,m)=>s+m.days,0)+calendar.months.slice(0,Number(ev.month)).reduce((s,m)=>s+m.days,0)+Number(ev.day)-1;}
export function mountNarrative(main,w,view,{modal,field,save,heading,btn,openDocument,notify,confirmDelete}){
const n=initNarrative(w),targets=loreTargets(w);let dispose=()=>{},selected='';const name=id=>targets.find(t=>t.id===id)?.name||'Referência removida';const options=(id='',empty=true)=>(empty?'<option value="">Sem referência</option>':'')+targets.map(t=>`<option value="${e(t.id)}" ${id===t.id?'selected':''}>${e(t.kind)} · ${e(t.name)}</option>`).join('');
const select=(label,key,value='',empty=true)=>`<label class="field"><span>${label}</span><select name="${key}">${options(value,empty)}</select></label>`;
const dateText=ev=>`${ev.day} de ${n.calendar.months[ev.month]?.name||'?'} · ${ev.year} ${n.calendar.era}`;
function editEvent(id){const ev=n.events.find(x=>x.id===id);modal(ev?'Editar acontecimento':'Novo acontecimento',`<p class="help timeline-form-help">Defina quando acontece. A cronologia organiza os acontecimentos pelas datas do seu calendário fictício.</p>`+field('Nome do acontecimento','title',ev?.title||'','text',true)+`<div class="field-grid">${field('Ano','year',ev?.year??1,'number',true)}<label class="field"><span>Mês</span><select name="month">${n.calendar.months.map((m,i)=>`<option value="${i}" ${ev?.month===i?'selected':''}>${e(m.name)}</option>`).join('')}</select></label>${field('Dia','day',ev?.day||1,'number',true)}</div>`+select('Vincular a um registro','target',ev?.target)+field('O que acontece?','description',ev?.description||'','textarea')+(ev?'<button type="button" id="removeEvent" class="text-link">Excluir acontecimento</button>':''),fd=>{const year=Number(fd.get('year')),month=Number(fd.get('month')),day=Number(fd.get('day'));if(!Number.isSafeInteger(year)||!Number.isInteger(month)||month<0||month>=n.calendar.months.length||!Number.isInteger(day)||day<1||day>n.calendar.months[month].days)throw Error('Confira o ano, o mês e o dia deste calendário.');const data={id:ev?.id||uid(),title:fd.get('title'),year,month,day,target:fd.get('target'),description:fd.get('description')};if(ev)Object.assign(ev,data);else n.events.push(data);save();render();});if(ev)document.querySelector('#removeEvent').onclick=()=>{document.querySelector('#modal').close();confirmDelete('Excluir acontecimento?','Este acontecimento será removido da cronologia.',()=>n.events=n.events.filter(x=>x.id!==id));};}
function calendarSettings(){modal('O tempo do seu mundo',field('Era','era',n.calendar.era,'text',true)+field('Meses: um por linha, nome | dias','months',n.calendar.months.map(m=>`${m.name} | ${m.days}`).join('\n'),'textarea',true)+field('Dias da semana, separados por vírgula','weekdays',n.calendar.weekdays.join(', '),'text',true)+'<p class="help">Exemplo: Aurora | 30. As datas dos eventos precisam continuar válidas após as alterações.</p>',fd=>{const months=String(fd.get('months')).split('\n').filter(x=>x.trim()).map(line=>{const parts=line.split('|');return {name:parts[0].trim(),days:Number(parts[1])};}),weekdays=String(fd.get('weekdays')).split(',').map(x=>x.trim()).filter(Boolean);if(!months.length||months.length>30||months.some(m=>!m.name||!Number.isInteger(m.days)||m.days<1||m.days>365)||!weekdays.length||weekdays.length>30)throw Error('Use de 1 a 30 meses e dias da semana; cada mês deve ter de 1 a 365 dias.');if(n.events.some(ev=>!months[ev.month]||ev.day>months[ev.month].days))throw Error('Há eventos em datas que seriam removidas. Ajuste esses eventos primeiro.');n.calendar={era:fd.get('era'),months,weekdays};save();render();});}
function render(){dispose();dispose=()=>{};if(view==='connections')graph();else if(view==='timeline')timeline();else scenes();}
function graph(){dispose=mountConnections(main,n,targets,{save,heading,notify,openDocument,documents:documentTargets(w),confirmDelete});}
function preview(id,container){const t=targets.find(x=>x.id===id);container.innerHTML=t?`<article class="lore-card"><small>${e(t.kind)}</small><h2>${e(t.name)}</h2><p>${e(t.description)}</p>${documentTargets(w).some(d=>d.id===id)?'<button class="button ghost" id="openLoreDoc">Abrir documento</button>':''}</article>`:'<p class="help">Esta referência foi removida.</p>';container.querySelector('#openLoreDoc')?.addEventListener('click',()=>openDocument(id));}
function timeline(){
 main.innerHTML=`<div class="page timeline-page">${heading('O TEMPO DO SEU UNIVERSO','Linha do tempo','Acompanhe como a história do seu mundo se desenrola.',btn('＋ Novo acontecimento','newLoreEvent'))}<section class="timeline-context"><button class="button ghost" id="loreCalendar" aria-label="Configurar calendário fictício">▦ <span>Calendário fictício</span></button><div class="timeline-calendar-summary"><strong>${e(n.calendar.era)}</strong><span>${n.calendar.months.length} meses</span><span>${n.calendar.weekdays.length} dias por semana</span></div><p>${n.events.length?`${n.events.length} ${n.events.length===1?'acontecimento registrado':'acontecimentos registrados'}`:'Datas e eventos organizados no calendário do seu mundo'}</p></section><div class="timeline-controls"><label class="timeline-search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/></svg><input id="timelineSearch" type="search" placeholder="Buscar acontecimento..." aria-label="Buscar acontecimento"></label><label class="timeline-sort"><span>Ordem</span><select id="timelineSort" aria-label="Ordem dos acontecimentos"><option value="asc">Mais antigos primeiro</option><option value="desc">Mais recentes primeiro</option></select></label></div><div id="timelineEvents" class="timeline-list" aria-live="polite"></div><div id="lorePreview" class="timeline-preview"></div></div>`;
 const list=main.querySelector('#timelineEvents'),search=main.querySelector('#timelineSearch'),sort=main.querySelector('#timelineSort');
 function drawEvents(){const query=search.value.trim().toLocaleLowerCase('pt-BR'),direction=sort.value==='desc'?-1:1,events=[...n.events].filter(ev=>[ev.title,ev.description,name(ev.target),dateText(ev)].join(' ').toLocaleLowerCase('pt-BR').includes(query)).sort((a,b)=>direction*(fictionalOrdinal(a,n.calendar)-fictionalOrdinal(b,n.calendar))||a.title.localeCompare(b.title,'pt-BR'));if(!events.length){list.innerHTML=n.events.length?'<div class="timeline-empty"><span>⌕</span><h2>Nenhum acontecimento encontrado</h2><p>Tente outro termo de busca.</p></div>':'<div class="timeline-empty"><span>✧</span><h2>Sua história começa com um acontecimento</h2><p>Registre eventos importantes e veja como eles se conectam no tempo.</p><button class="button" data-add-event>＋ Criar primeiro acontecimento</button></div>';list.querySelector('[data-add-event]')?.addEventListener('click',()=>editEvent());return;}
  const groups=new Map();for(const ev of events){const key=String(ev.year);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(ev);}list.innerHTML=[...groups].map(([year,items])=>`<section class="timeline-year-group"><h2 class="timeline-year-heading"><span>Ano ${e(year)}</span><small>${e(n.calendar.era)}</small></h2><div class="timeline-year-events">${items.map(ev=>{const weekday=n.calendar.weekdays[((fictionalOrdinal(ev,n.calendar)%n.calendar.weekdays.length)+n.calendar.weekdays.length)%n.calendar.weekdays.length];return `<article class="timeline-event"><div class="timeline-date"><strong>${String(ev.day).padStart(2,'0')}</strong><span>${e(n.calendar.months[ev.month]?.name||'Mês')}</span><small>${e(weekday)}</small></div><div class="timeline-event-body"><div class="timeline-event-heading"><h3>${e(ev.title)}</h3><span class="timeline-event-kind">Acontecimento</span></div>${ev.description?`<p>${e(ev.description)}</p>`:''}${ev.target?`<button class="timeline-reference" data-target="${e(ev.target)}"><span>↗</span>${e(name(ev.target))}</button>`:''}<div class="timeline-event-actions"><button type="button" class="timeline-edit" data-event="${e(ev.id)}">✎ Editar</button></div></div></article>`;}).join('')}</div></section>`).join('');list.querySelectorAll('[data-event]').forEach(button=>button.addEventListener('click',()=>editEvent(button.dataset.event)));list.querySelectorAll('[data-target]').forEach(button=>button.addEventListener('click',()=>preview(button.dataset.target,main.querySelector('#lorePreview'))));}
 main.querySelector('#loreCalendar').onclick=calendarSettings;main.querySelector('[data-action="newLoreEvent"]').onclick=()=>editEvent();search.addEventListener('input',drawEvents);sort.addEventListener('change',drawEvents);drawEvents();
}
function scenes(){const scene=n.scenes.find(s=>s.id===selected)||n.scenes[0];selected=scene?.id||'';main.innerHTML=`<div class="page">${heading('ESCREVA COM SEU MUNDO POR PERTO','Cenas','Seu manuscrito, com as referências ao alcance dos olhos.',btn('＋ Nova cena','newScene'))}<div class="editor-layout scene-workspace"><nav class="note-list" aria-label="Cenas">${n.scenes.map(s=>`<button class="note-item ${s.id===selected?'active':''}" data-scene="${s.id}"><strong>${e(s.title)}</strong><small>${plain(s.body).split(/\s+/).filter(Boolean).length} palavras</small></button>`).join('')}</nav>${scene?`<section>${editorMarkup(scene).replace('<button class="text-link" data-action="deleteNote">Excluir documento</button>','')}<button class="text-link" id="deleteScene">Excluir cena</button></section><aside class="scene-references" aria-label="Referências da cena"></aside>`:'<div class="empty"><h2>Uma cena, muitas possibilidades.</h2><p>Crie a primeira cena para começar.</p></div>'}</div></div>`;main.querySelector('[data-action="newScene"]').onclick=()=>modal('Nova cena',field('Título','title','','text',true),fd=>{const s={id:uid(),title:fd.get('title'),body:'',references:[],updated:new Date().toISOString()};n.scenes.push(s);selected=s.id;save();render();});main.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{selected=b.dataset.scene;render();});if(!scene)return;dispose=mountEditor(scene,{onChange:save,onTitle:()=>{save();const b=main.querySelector('.note-item.active strong');if(b)b.textContent=scene.title;},notify,documents:documentTargets(w),openDocument});const editorCleanup=dispose,refsCleanup=mountSceneReferences(main.querySelector('.scene-references'),scene,targets,n.events,{save,openDocument,documents:documentTargets(w),dateText});dispose=()=>{editorCleanup();refsCleanup();};main.querySelector('#deleteScene').onclick=()=>confirmDelete('Excluir cena?','O texto desta cena será removido.',()=>n.scenes=n.scenes.filter(s=>s.id!==scene.id));}
render();return ()=>dispose();
}
